window.STUDY_EXAM_CURATED={"beginner":[{"id":"CB-G-05","section":"grammar","lesson":5,"unitIds":["B8-G5-0-0"],"prompt":"要表达“昨天是休息日”的过去肯定判断，空白处应选哪一项？","options":["でした","です","ではありません","ではありませんでした"],"answer":"でした","explanation":"でした是です的过去肯定形式。です是非过去肯定；ではありません是否定；ではありませんでした是过去否定。","point":"判断句的过去肯定","gap":{"unitId":"B8-G5-0-0","start":5,"end":8},"sourceRoute":"lesson/5/notes/0","sourceLabel":"第5课 · 判断句的过去肯定"},{"id":"CB-G-06","section":"grammar","lesson":6,"unitIds":["B8-G6-2-0"],"prompt":"句子说明妹妹在房间里。表示有生命的人存在，应填哪一项？","options":["います","あります","でした","でしょう"],"answer":"います","explanation":"妹妹是人，说明其所在使用います。あります一般用于无生命物体；でした和でしょう都是判断形式，不能接在这里的地点に后表达人的存在。","point":"有生命对象的存在","gap":{"unitId":"B8-G6-2-0","start":5,"end":8},"sourceRoute":"lesson/6/notes/2","sourceLabel":"第6课 · 有生命对象的存在"},{"id":"CB-G-07","section":"grammar","lesson":7,"unitIds":["B8-G7-1-0"],"prompt":"空白处要表达“昨天不冷”，即い形容词的过去否定，应选哪一项？","options":["寒くなかった","寒くない","寒かった","寒い"],"answer":"寒くなかった","explanation":"寒い先把末尾い变成く，再接なかった，得到过去否定寒くなかった。寒くない是否定非过去；寒かった是过去肯定；寒い是非过去肯定。","point":"い形容词的过去否定","gap":{"unitId":"B8-G7-1-0","start":3,"end":9},"sourceRoute":"lesson/7/notes/1","sourceLabel":"第7课 · い形容词的过去否定"},{"id":"CB-G-08","section":"grammar","lesson":8,"unitIds":["B8-G8-1-0"],"prompt":"要说明这座城镇“以前很安静”，空白处应使用哪种礼貌过去肯定形式？","options":["静かでした","静かです","静かではありません","静かな"],"answer":"静かでした","explanation":"静か是な形容词，礼貌过去肯定为静かでした。静かな用于修饰后面的名词，不能独立承担这里的句末谓语。","point":"な形容词的过去肯定","gap":{"unitId":"B8-G8-1-0","start":6,"end":11},"sourceRoute":"lesson/8/notes/1","sourceLabel":"第8课 · な形容词的过去肯定"},{"id":"CB-G-09","section":"grammar","lesson":9,"unitIds":["B8-G9-1-0"],"prompt":"按本课动词“読む”的ます形补全句子。","options":["読みます","読むます","読んます","読まます"],"answer":"読みます","explanation":"読む是五段动词，接ます时，末尾む变为い段的み，得到読みます。不是在辞书形読む后直接加ます。","point":"五段动词的ます形","gap":{"unitId":"B8-G9-1-0","start":5,"end":9},"sourceRoute":"lesson/9/notes/1","sourceLabel":"第9课 · 五段动词的ます形"},{"id":"CB-G-10","section":"grammar","lesson":10,"unitIds":["B8-G10-0-0"],"prompt":"要表达“昨天没有读书”的礼貌过去否定，空白处应选哪一项？","options":["読みませんでした","読みました","読みます","読みません"],"answer":"読みませんでした","explanation":"読みませんでした同时表示礼貌、否定和过去。読みました是过去肯定；読みません是否定非过去；読みます是肯定非过去。","point":"动词的礼貌过去否定","gap":{"unitId":"B8-G10-0-0","start":5,"end":13},"sourceRoute":"lesson/10/notes/0","sourceLabel":"第10课 · 动词的礼貌过去否定"},{"id":"CB-G-11","section":"grammar","lesson":11,"unitIds":["B8-G11-0-0"],"prompt":"将“書く”变成て形，再接ください提出请求，应填哪一项？","options":["書いて","書って","書んで","書きて"],"answer":"書いて","explanation":"書く是以く结尾的五段动词，て形发生イ音便，变为書いて。書き是接ます的连用形，这里不直接写成書きて。","point":"く结尾动词的て形","gap":{"unitId":"B8-G11-0-0","start":3,"end":6},"sourceRoute":"lesson/11/notes/0","sourceLabel":"第11课 · く结尾动词的て形"},{"id":"CB-G-12","section":"grammar","lesson":12,"unitIds":["B8-G12-2-0"],"prompt":"用本课表示本人“打算”的句型，表达计划明年去日本留学，应填哪一项？","options":["つもり","はず","ところ","ほど"],"answer":"つもり","explanation":"动词辞书形＋つもりです表示本人已经有的打算。はず表示根据理由作出的预期；ところ表示动作阶段；ほど表示程度。","point":"つもり表示打算","gap":{"unitId":"B8-G12-2-0","start":10,"end":13},"sourceRoute":"lesson/12/notes/2","sourceLabel":"第12课 · つもり表示打算"},{"id":"CB-G-13","section":"grammar","lesson":13,"unitIds":["B8-G13-2-0"],"prompt":"要表达“可以在这里学习日语”的能力或条件许可，应填哪一项？","options":["ことができます","ことがあります","ことをします","ことであります"],"answer":"ことができます","explanation":"动词辞书形＋ことができます表达能够做某事。ことがあります表达某种事情会发生或有时发生，不能代替本句的“能够”。","point":"辞书形＋ことができる","gap":{"unitId":"B8-G13-2-0","start":11,"end":18},"sourceRoute":"lesson/13/notes/2","sourceLabel":"第13课 · 辞书形＋ことができる"},{"id":"CB-G-14","section":"grammar","lesson":14,"unitIds":["B8-G14-4-0"],"prompt":"要用“～たことがあります”表示去过京都的经历，行く应变成哪种形式？","options":["行った","行く","行って","行こう"],"answer":"行った","explanation":"表达过去的经历，使用动词た形＋ことがあります。行く的た形是特殊的行った；行くことがあります会表示有时去，不是去过。","point":"たことがある表示经历","gap":{"unitId":"B8-G14-4-0","start":3,"end":6},"sourceRoute":"lesson/14/notes/4","sourceLabel":"第14课 · たことがある表示经历"},{"id":"CB-G-15","section":"grammar","lesson":15,"unitIds":["B8-G15-0-0"],"prompt":"主语是朋友，接受书的人是说话人“我”。站在自己接受朋友馈赠的立场，选择合适的授受动词。","options":["くれました","あげました","もらいました","やりました"],"answer":"くれました","explanation":"朋友把书给说话人，站在说话人的立场使用くれる。もらう的主语应是接受者；あげる、やる表示给出去的方向。","point":"くれる的授受方向","gap":{"unitId":"B8-G15-0-0","start":7,"end":12},"sourceRoute":"lesson/15/notes/0","sourceLabel":"第15课 · くれる的授受方向"},{"id":"CB-G-16","section":"grammar","lesson":16,"unitIds":["B8-G16-2-0"],"prompt":"本句要明确表达“这里禁止吸烟”，在吸って后应接哪一项？","options":["はいけません","もいいです","ください","みます"],"answer":"はいけません","explanation":"动词て形＋はいけません表示禁止。てもいいです表示许可；てください表示请求对方做；てみます表示尝试做。","point":"てはいけない表示禁止","gap":{"unitId":"B8-G16-2-0","start":10,"end":16},"sourceRoute":"lesson/16/notes/2","sourceLabel":"第16课 · てはいけない表示禁止"},{"id":"CB-G-17","section":"grammar","lesson":17,"unitIds":["B8-G17-6-0"],"prompt":"将読む接到なさい前，构成“仔细读题”的命令，应填哪一项？","options":["読み","読む","読んで","読もう"],"answer":"読み","explanation":"なさい接动词ます形去ます后的形式。読む→読みます→読み，所以是読みなさい。","point":"ます形去ます＋なさい","gap":{"unitId":"B8-G17-6-0","start":5,"end":7},"sourceRoute":"lesson/17/notes/6","sourceLabel":"第17课 · ます形去ます＋なさい"},{"id":"CB-G-18","section":"grammar","lesson":18,"unitIds":["B8-G18-6-0"],"prompt":"要表达“今天只能学习三十分钟”，并与句末できません配合，应填哪一项？","options":["しか","だけ","まで","こそ"],"answer":"しか","explanation":"数量＋しか＋否定谓语表示“只有这么多”。三十分しか勉強できません整体表达能学习的时间仅有三十分钟，不能只按句末否定理解为完全不能学习。","point":"しか与否定谓语","gap":{"unitId":"B8-G18-6-0","start":6,"end":8},"sourceRoute":"lesson/18/notes/6","sourceLabel":"第18课 · しか与否定谓语"},{"id":"CB-G-19","section":"grammar","lesson":19,"unitIds":["B8-G19-5-0"],"prompt":"要表达这个说明“容易理解”，在分かり后应接哪一项？","options":["やすい","にくい","過ぎる","がたい"],"answer":"やすい","explanation":"分かる的ます形去ます为分かり，接やすい表示容易理解。にくい、がたい都偏向难以做到；過ぎる表示过度。","point":"ます形去ます＋やすい","gap":{"unitId":"B8-G19-5-0","start":8,"end":11},"sourceRoute":"lesson/19/notes/5","sourceLabel":"第19课 · ます形去ます＋やすい"},{"id":"CB-G-20","section":"grammar","lesson":20,"unitIds":["B8-G20-9-0"],"prompt":"用本课“越练习越熟练”的对应关系补全句子。","options":["するほど","してから","したばかり","しないうちに"],"answer":"するほど","explanation":"練習すればするほど采用同一动词的ば形＋辞书形＋ほど，表示程度随之增长。してから表示先后，したばかり表示刚做过，しないうちに表示趁还未做。","point":"ば～ほど的对应变化","gap":{"unitId":"B8-G20-9-0","start":5,"end":9},"sourceRoute":"lesson/20/notes/9","sourceLabel":"第20课 · ば～ほど的对应变化"},{"id":"CB-G-21","section":"grammar","lesson":21,"unitIds":["B8-G21-4-0"],"prompt":"たった今说明刚刚发生；要表达“课刚刚结束”，ところです前应选哪一项？","options":["終わった","終わる","終わっている","終わらない"],"answer":"終わった","explanation":"动词た形＋ところです表示动作刚完成。辞书形＋ところです表示正要做，ている＋ところです表示正在进行。","point":"たところ表示刚完成","gap":{"unitId":"B8-G21-4-0","start":8,"end":12},"sourceRoute":"lesson/21/notes/4","sourceLabel":"第21课 · たところ表示刚完成"},{"id":"CB-G-22","section":"grammar","lesson":22,"unitIds":["B8-G22-2-0"],"prompt":"说话人根据蛋糕的外观判断它“看起来好吃”。应选择哪种そう的接法？","options":["美味しそう","美味しいそう","美味しくそう","美味しくないそう"],"answer":"美味しそう","explanation":"表示外观样态时，い形容词去末尾い接そう：美味しい→美味しそう。美味しいそうです则是传闻，表示听说好吃。","point":"样态そう与传闻そう","gap":{"unitId":"B8-G22-2-0","start":6,"end":11},"sourceRoute":"lesson/22/notes/2","sourceLabel":"第22课 · 样态そう与传闻そう"},{"id":"CB-G-23","section":"grammar","lesson":23,"unitIds":["B8-G23-0-0"],"prompt":"要强调导览图已经被人贴好、目前保持着该状态，应填哪一项？","options":["貼ってあります","貼ります","貼らせます","貼りたいです"],"answer":"貼ってあります","explanation":"他动词て形＋ある表示有人有意做过某事后留下的结果状态。案内図が貼ってあります说明图已经贴在那里，而不是将来要贴或想贴。","point":"てある的结果状态","gap":{"unitId":"B8-G23-0-0","start":7,"end":14},"sourceRoute":"lesson/23/notes/0","sourceLabel":"第23课 · てある的结果状态"},{"id":"CB-G-24","section":"grammar","lesson":24,"unitIds":["B8-G24-2-0"],"prompt":"请用传闻助动词そうです转述天气预报“明天会下雨”的消息；空白处应填哪一项？","options":["降るそうです","降りそうです","降ったところです","降ってみます"],"answer":"降るそうです","explanation":"伝聞そうだ接动词普通形，所以降るそうです表示听说明天会下雨。降りそうです是ます形去ます＋样态そう，表示看起来快要下雨。","point":"传闻そう的接续","gap":{"unitId":"B8-G24-2-0","start":14,"end":20},"sourceRoute":"lesson/24/notes/2","sourceLabel":"第24课 · 传闻そう的接续"},{"id":"CB-G-25","section":"grammar","lesson":25,"unitIds":["B8-G25-6-0"],"prompt":"说话人正在安排接下来要做的课前准备，要表达“我会预先查好新单词”，应选哪一项？","options":["調べておきます","調べてしまいました","調べたばかりです","調べてもらいました"],"answer":"調べておきます","explanation":"动词て形＋おく表示为了后面的事情预先做好准备。本句的授業の前に与調べておきます共同说明课前准备。","point":"ておく表示预先准备","gap":{"unitId":"B8-G25-6-0","start":12,"end":19},"sourceRoute":"lesson/25/notes/6","sourceLabel":"第25课 · ておく表示预先准备"},{"id":"CB-G-26","section":"grammar","lesson":26,"unitIds":["B8-G26-4-0"],"prompt":"要表达“做完作业后再去散步”，应选哪一项？","options":["したあとで","する前に","している間に","しないまま"],"answer":"したあとで","explanation":"动词た形＋あとで表示前项完成以后再做后项。する前に把顺序倒过来；している間に表示进行期间；しないまま表示没做作业就去。","point":"た形＋あとで","gap":{"unitId":"B8-G26-4-0","start":3,"end":8},"sourceRoute":"lesson/26/notes/4","sourceLabel":"第26课 · た形＋あとで"},{"id":"CB-G-27","section":"grammar","lesson":27,"unitIds":["B8-G27-0-0"],"prompt":"要用読む的可能形式表达“我能读日语报纸”，应填哪一项？","options":["読めます","読みます","読ませます","読まれます"],"answer":"読めます","explanation":"五段动词読む构成可能动词时，む变为え段的め，再接る，得到読める；其礼貌形为読めます。読みます只陈述读的动作，読ませます是使役。","point":"五段动词的可能形式","gap":{"unitId":"B8-G27-0-0","start":9,"end":13},"sourceRoute":"lesson/27/notes/0","sourceLabel":"第27课 · 五段动词的可能形式"},{"id":"CB-G-28","section":"grammar","lesson":28,"unitIds":["B8-G28-3-1"],"prompt":"句子是在询问老师回去的时间，要尊敬老师的动作，应选哪一项？","options":["お帰りになります","お帰りします","お帰りいたします","帰ってあげます"],"answer":"お帰りになります","explanation":"お＋动词ます形去ます＋になる是尊敬句型，用于抬高老师的动作。お帰りします、いたします属于自谦方向，不能用来尊敬对方回去的动作。","point":"お～になる尊敬句型","gap":{"unitId":"B8-G28-3-1","start":6,"end":14},"sourceRoute":"lesson/28/notes/3","sourceLabel":"第28课 · お～になる尊敬句型"},{"id":"CB-G-29","section":"grammar","lesson":29,"unitIds":["B8-G29-6-0"],"prompt":"句子说词典是“上周才买的”，强调在说话人感觉中买来不久，应填哪一项？","options":["ばかり","ところ","つもり","よう"],"answer":"ばかり","explanation":"たばかり表示说话人认为动作完成不久，能与先週这样的时间搭配。たところ强调刚完成的即时阶段，通常不与“上周”搭配。","point":"たばかり与たところ","gap":{"unitId":"B8-G29-6-0","start":10,"end":13},"sourceRoute":"lesson/29/notes/6","sourceLabel":"第29课 · たばかり与たところ"},{"id":"CB-G-30","section":"grammar","lesson":30,"unitIds":["B8-G30-1-0"],"prompt":"要表达“只要有时间这一条件，就能每天练习”，应填哪一项？","options":["さえ","しか","まで","こそ"],"answer":"さえ","explanation":"名词＋さえ＋ば形表示最低限度的充分条件。時間さえあれば说明只要时间这一条件得到满足就能练习；しか通常需要配合否定谓语。","point":"さえ～ば表示最低条件","gap":{"unitId":"B8-G30-1-0","start":2,"end":4},"sourceRoute":"lesson/30/notes/1","sourceLabel":"第30课 · さえ～ば表示最低条件"},{"id":"CB-R-05","section":"reading","lesson":5,"unitIds":["L5-B002","L5-B003","L5-B004"],"prompt":"这段自我介绍中的王明，目前的身份是哪一项？","options":["清华大学计算机系二年级学生","清华大学护理专业三年级学生","早稻田大学汉语专业三年级学生","从事计算机工作的研究生"],"answer":"清华大学计算机系二年级学生","explanation":"清華大学の学生、コンピューター学部の2年生共同限定了学校、院系与年级。片段没有说他是护理专业学生、早稻田学生或研究生。","point":"自我介绍中的身份信息","sourceRoute":"lesson/5/reading/body/1","sourceLabel":"第5课 · 课文／会话精读"},{"id":"CB-R-06","section":"reading","lesson":6,"unitIds":["L6-B003","L6-B004","L6-B005"],"prompt":"根据这段介绍，说话人的哪些家人住在名古屋？","options":["父母和哥哥","父母、哥哥和姐姐","只有父母","哥哥和姐姐"],"answer":"父母和哥哥","explanation":"両親と兄は名古屋にいます明确给出父母与哥哥。前一句列的是全家成员，不能把那一句中的姐姐也算进名古屋居住者。","point":"区分家庭成员与居住地点","sourceRoute":"lesson/6/reading/body/2","sourceLabel":"第6课 · 课文／会话精读"},{"id":"CB-R-07","section":"reading","lesson":7,"unitIds":["L7-B008","L7-B009","L7-B010"],"prompt":"根据片段，为什么东京十月也是适合运动的季节？","options":["天气不热也不冷","东京十月的雪特别多","东京十月比北京更闷热","运动只能在十月进行"],"answer":"天气不热也不冷","explanation":"10月は暑くも寒くもありません先说明气温适宜，下一句接着说スポーツにもいい季節です。其他选项把别的季节特征或不存在的限制加进了片段。","point":"联系相邻句理解理由","sourceRoute":"lesson/7/reading/body/7","sourceLabel":"第7课 · 课文／会话精读"},{"id":"CB-R-08","section":"reading","lesson":8,"unitIds":["L8-B009","L8-B010","L8-B011"],"prompt":"そんな東京ですが在这里引出了什么内容？","options":["尽管街道清洁，东京仍有地震多、物价高等问题","因为街道不干净，东京物价变高了","东京交通便利，因此没有其他问题","东京只有地震问题，没有生活成本问题"],"answer":"尽管街道清洁，东京仍有地震多、物价高等问题","explanation":"前一句说街道清洁，ですが转入问题：地震が多く、物価も高い。它表示转折，并没有建立“街道脏导致涨价”的因果。","point":"转折句与问题列举","sourceRoute":"lesson/8/reading/body/8","sourceLabel":"第8课 · 课文／会话精读"},{"id":"CB-R-09","section":"reading","lesson":9,"unitIds":["L9-B016","L9-B017","L9-B018"],"prompt":"说话人星期六下午的家教兼职是做什么？","options":["教高中生英语","教大学生汉语","在宿舍教吉他","在食堂教做饭"],"answer":"教高中生英语","explanation":"午前中洗濯、午後家庭教師后，接着用高校生に英語を教えます具体说明兼职内容。这里应把下午与高中生、英语相联系。","point":"时间与活动对象对应","sourceRoute":"lesson/9/reading/body/15","sourceLabel":"第9课 · 课文／会话精读"},{"id":"CB-R-10","section":"reading","lesson":10,"unitIds":["L10-B012","L10-B013","L10-B014"],"prompt":"王同学最后为什么改买了毛衣？","options":["看中的大衣价格太高，所以没有买","百货商店完全没有大衣","她一开始只想买毛衣","大衣不允许试穿"],"answer":"看中的大衣价格太高，所以没有买","explanation":"片段先说想要大衣而去百货商店，随后说いいコートがありましたが、高かったので買いませんでした，最后代わりに买毛衣。原因是贵，而不是没有大衣。","point":"因果与替代选择","sourceRoute":"lesson/10/reading/body/11","sourceLabel":"第10课 · 课文／会话精读"},{"id":"CB-R-11","section":"reading","lesson":11,"unitIds":["L11-B003","L11-B006","L11-B007"],"prompt":"这段话中的“我”打算在哪里等待对方？","options":["机场的到达大厅","东京大学的研究室","公司的会议室","机场的出发大厅"],"answer":"机场的到达大厅","explanation":"空港の到着ロビーで待っています直接给出等待地点。迎えに行きます说明是去接到达的朋友，因此也不能把到着大厅看成出发大厅。","point":"接机安排中的地点","sourceRoute":"lesson/11/reading/body/2","sourceLabel":"第11课 · 课文／会话精读"},{"id":"CB-R-12","section":"reading","lesson":12,"unitIds":["L12-B009","L12-B010","L12-B011"],"prompt":"作者对留学变得容易这件事有什么保留意见？","options":["留学容易是好事，但不少人不认真学习，这并不好","留学越困难就越值得支持","只要出国，就不需要认真学习","作者认为所有留学生都不学习"],"answer":"留学容易是好事，但不少人不认真学习，这并不好","explanation":"いいことです先肯定留学容易，しかし转入一生懸命勉強しない人が少なくありません，随后明确否定这种现象。少なくない表示不少，不是所有人。","point":"区分肯定对象与批评对象","sourceRoute":"lesson/12/reading/body/8","sourceLabel":"第12课 · 课文／会话精读"},{"id":"CB-R-13","section":"reading","lesson":13,"unitIds":["L13-B004","L13-B005","L13-B006"],"prompt":"与过去寄信相比，片段强调电子邮件的哪项优势？","options":["可以立刻发送消息和照片","可以避免所有互联网问题","可以保证收件人一定立即回复","可以直接代替出国旅行"],"answer":"可以立刻发送消息和照片","explanation":"书信要何日も，而Eメール能すぐにメッセージや写真を送る。重点是发送速度与内容，片段没有保证回复速度，也没有宣称互联网没有问题。","point":"比较旧方式与新方式","sourceRoute":"lesson/13/reading/body/3","sourceLabel":"第13课 · 课文／会话精读"},{"id":"CB-R-14","section":"reading","lesson":14,"unitIds":["L14-B015","L14-B016","L14-B017"],"prompt":"说话人没有给儿子买鞋的直接理由是什么？","options":["儿子已经有很多鞋了","商店已经关门了","父亲没有看见儿子想买的鞋","那双鞋没有儿子的尺码"],"answer":"儿子已经有很多鞋了","explanation":"买不买的直接理由由すでにたくさん持っているので给出，即已经有很多。500元强调价格高，但片段明确使用ので说明的是已有很多鞋。","point":"识别ので标记的直接理由","sourceRoute":"lesson/14/reading/body/14","sourceLabel":"第14课 · 课文／会话精读"},{"id":"CB-R-15","section":"reading","lesson":15,"unitIds":["L15-B009","L15-B010","L15-B011"],"prompt":"作者为什么提醒收到巧克力的男性先认真想一想？","options":["礼物可能只是出于人际交往，并不一定表示爱情","送巧克力的人一定讨厌收礼者","巧克力一定是上司送来的","所有巧克力都必须立即退还"],"answer":"礼物可能只是出于人际交往，并不一定表示爱情","explanation":"片段说女性爱着收礼者的概率并没有那么高，并解释出于付き合い送的義理チョコ。应区分礼物这一行为与爱情表白，不能断定一定有爱或一定讨厌。","point":"辨别礼物的交往含义","sourceRoute":"lesson/15/reading/body/8","sourceLabel":"第15课 · 课文／会话精读"},{"id":"CB-R-16","section":"reading","lesson":16,"unitIds":["L16-B010","L16-B011","L16-B012"],"prompt":"按片段所说，丢垃圾时需要同时留意什么？","options":["可丢弃的星期、时间和垃圾种类","只要时间正确，任何垃圾都能丢","只需把垃圾放到离家最近的地方","只有垃圾数量有限制，日期不重要"],"answer":"可丢弃的星期、时间和垃圾种类","explanation":"片段连续列出曜日と時間以及曜日ごとの種類，并说规定种类以外不能丢。因此时间、日期与种类需要一起核对。","point":"整合多个条件","sourceRoute":"lesson/16/reading/body/9","sourceLabel":"第16课 · 课文／会话精读"},{"id":"CB-R-17","section":"reading","lesson":17,"unitIds":["L17-B010","L17-B011","L17-B012"],"prompt":"这三句描写了哪些社会与家庭现象？","options":["女性上大学、婚后工作已很常见，双职工家庭的男性也帮做家务","女性结婚后都不能继续工作","现代男性几乎不参与任何家务","男女双方都不再需要接受大学教育"],"answer":"女性上大学、婚后工作已很常见，双职工家庭的男性也帮做家务","explanation":"片段分别说女性上大学已很常见、婚后继续工作是普通的事，夫妻双方都工作的家庭里男性也帮忙做家务。它没有说女性结婚后不能工作，也没有说男性完全不参与家务。","point":"用事例理解社会变化","sourceRoute":"lesson/17/reading/body/9","sourceLabel":"第17课 · 课文／会话精读"},{"id":"CB-R-18","section":"reading","lesson":18,"unitIds":["L18-B003","L18-B004","L18-B005"],"prompt":"同样因为“人生只有一次”，为什么有人愿意花大钱，有人却觉得不值得？","options":["有人重视仪式的唯一性，有人重视衣服只穿一次的成本","所有人都只愿意穿日常服装","所有人都认为价格越高越好","两类人其实都不准备参加成人仪式"],"answer":"有人重视仪式的唯一性，有人重视衣服只穿一次的成本","explanation":"一方把一生に一度看成值得投入的理由，另一方则把一生に一回しか着ない看成不值得付高价的理由。差异在于评价角度，并不是是否参加仪式。","point":"比较同一事实的不同评价","sourceRoute":"lesson/18/reading/body/3","sourceLabel":"第18课 · 课文／会话精读"},{"id":"CB-R-19","section":"reading","lesson":19,"unitIds":["L19-B006","L19-B007","L19-B008"],"prompt":"作者为什么说保护环境“说起来容易，做起来难”？","options":["人们长期为个人经济利益而牺牲自然","作者认为环境问题根本不存在","因为人们不知道海洋和河流在哪里","因为每个人都已经停止砍伐树木"],"answer":"人们长期为个人经济利益而牺牲自然","explanation":"なぜなら后的理由是人类常牺牲自然，下一句用为个人经济利益砍树、污染海河具体说明。句子强调利益与保护之间的冲突。","point":"なぜなら引出的论证理由","sourceRoute":"lesson/19/reading/body/5","sourceLabel":"第19课 · 课文／会话精读"},{"id":"CB-R-20","section":"reading","lesson":20,"unitIds":["L20-B007","L20-B008","L20-B009"],"prompt":"这几句主要说明日语继续学下去时会遇到哪些困难？","options":["新单词越来越多，还要掌握词形变化和复杂的敬语","学会假名后就不再出现新的学习内容","动词和形容词完全没有变化","所有汉字的读音都能直接从汉语推出来"],"answer":"新单词越来越多，还要掌握词形变化和复杂的敬语","explanation":"片段依次提到知らない単語增加、必须逐一记忆，以及动词形容词变化和敬语复杂。它不是说学会假名便已完成日语学习。","point":"归纳学习难点","sourceRoute":"lesson/20/reading/body/6","sourceLabel":"第20课 · 课文／会话精读"},{"id":"CB-R-21","section":"reading","lesson":21,"unitIds":["L21-B008","L21-B009","L21-B010"],"prompt":"片段提醒，过度依赖电脑管理生活会有哪种风险？","options":["停电或电脑故障可能让基本生活功能无法正常运作","电脑越方便，停电就越不可能发生","只要用了电脑就永远不必维修水电","所有电脑故障都只会影响看电视"],"answer":"停电或电脑故障可能让基本生活功能无法正常运作","explanation":"问题由停电与故障两个条件展开：停电会什么都做不了，电脑故障甚至让电和水道停止。作者提醒的是依赖关系带来的脆弱性。","point":"理解便利背后的依赖风险","sourceRoute":"lesson/21/reading/body/7","sourceLabel":"第21课 · 课文／会话精读"},{"id":"CB-R-22","section":"reading","lesson":22,"unitIds":["L22-B016","L22-B017","L22-B018"],"prompt":"贵船给说话人的感受与闷热的京都有什么不同？","options":["店下流过冷水，让人在这里仿佛忘记了暑气","这里比京都其他地方更像桑拿房","这里所有河水都是热的","说话人在这里完全没有看到水"],"answer":"店下流过冷水，让人在这里仿佛忘记了暑气","explanation":"冷たい水が流れている先给出现场条件，接着说ここにいると暑さを忘れそうだった。应理解为当地清凉体验，而不是把整个京都说成寒冷。","point":"地点对比与感受","sourceRoute":"lesson/22/reading/body/15","sourceLabel":"第22课 · 课文／会话精读"},{"id":"CB-R-23","section":"reading","lesson":23,"unitIds":["L23-B006","L23-B007","L23-B008"],"prompt":"それだけではない后，作者怎样说明便利店不只是卖商品？","options":["举出照片冲印、委托寄件、复印和缴电费等服务","说明便利店只出售牛奶和书","说明所有便利店都提供免费的海外旅行","说明电费只能去银行或邮局缴纳"],"answer":"举出照片冲印、委托寄件、复印和缴电费等服务","explanation":"前句说若只是销售商品就与超市相似，后两句列出DPE、配達依赖、コピー及电费缴纳。不是所有服务免费，也不是电费只能去银行。","point":"把总述与具体服务对应","sourceRoute":"lesson/23/reading/body/5","sourceLabel":"第23课 · 课文／会话精读"},{"id":"CB-R-24","section":"reading","lesson":24,"unitIds":["L24-D010","L24-D011"],"prompt":"根据这段最新消息，片段中提到的同学目前在哪里休息？","options":["已经出院，在宿舍休息","仍在车站前的医院里住院","正在教室里上课","正在车站等候老师"],"answer":"已经出院，在宿舍休息","explanation":"D010给出以前住院的医院，D011接着用でも说明已经好转并出院，现在在寮休息。应依据后一句更新后的状态作答。","point":"转折后的最新状态","sourceRoute":"lesson/24/reading/dialogue/9","sourceLabel":"第24课 · 课文／会话精读"},{"id":"CB-R-25","section":"reading","lesson":25,"unitIds":["L25-B006","L25-B007","L25-B008"],"prompt":"说话人为什么觉得自己被安排教包饺子很为难？","options":["她从没包过饺子，也几乎没有烹饪知识，却要开料理课堂","她已经教过很多次，觉得工作重复","她在中国开过一家饺子店，太忙没有时间","她认为在日本完全买不到做饺子的材料"],"answer":"她从没包过饺子，也几乎没有烹饪知识，却要开料理课堂","explanation":"困った之后的理由是从未包过、不喜欢饺子，大学时一直在食堂吃饭，没有料理知识，没想到会被要求开料理课堂。其他选项没有片段依据。","point":"解释人物为难的原因","sourceRoute":"lesson/25/reading/body/5","sourceLabel":"第25课 · 课文／会话精读"},{"id":"CB-R-26","section":"reading","lesson":26,"unitIds":["L26-B007","L26-B008"],"prompt":"为什么有些在日本生活的人选择租房来解决居住问题？","options":["经常有工作调动，即使买房也可能又要搬家","作者说日本所有人都不能买房","租房者都不需要任何家具","买房后法律上永远不能搬家"],"answer":"经常有工作调动，即使买房也可能又要搬家","explanation":"片段先说租房的人也不少，接着以転勤が多く解释：好不容易买了房，也可能因调动不得不搬家。它没有说所有人不能买房。","point":"识别行为背后的生活条件","sourceRoute":"lesson/26/reading/body/6","sourceLabel":"第26课 · 课文／会话精读"},{"id":"CB-R-27","section":"reading","lesson":27,"unitIds":["L27-B009","L27-B010","L27-B011"],"prompt":"作者认为，钱多的人怎样才能真正掌握知识？","options":["仍然必须认真学习，财富不能代替这个过程","只要足够有钱，就能直接买到全部知识","只需住进宽敞的房子，不必读书","不需要学习，只要去国外旅行就行"],"answer":"仍然必须认真学习，财富不能代替这个过程","explanation":"作者把学问与人心列为钱买不到的东西，并用一生懸命勉強しない限り说明：无论多富有，不认真学习便不能掌握知识。","point":"ない限り与必要条件","sourceRoute":"lesson/27/reading/body/8","sourceLabel":"第27课 · 课文／会话精读"},{"id":"CB-R-28","section":"reading","lesson":28,"unitIds":["L28-B013","L28-B014","L28-B015"],"prompt":"关于论文，写信人打算完成后做什么？","options":["马上寄给老师，并希望听到老师的感想","先把论文交给从未联系过的陌生人","不再与老师联系","因为写作困难，所以已经决定放弃论文"],"answer":"马上寄给老师，并希望听到老师的感想","explanation":"完成したらすぐお送りいたします给出完成后的动作，下一句ご感想を伺う说明希望听取老师的感想。前一句也表示虽不容易，但似乎能完成，并非放弃。","point":"完成后的计划与请求","sourceRoute":"lesson/28/reading/body/12","sourceLabel":"第28课 · 课文／会话精读"},{"id":"CB-R-29","section":"reading","lesson":29,"unitIds":["L29-B010","L29-B011","L29-B012"],"prompt":"作者如何把最初汉语考试成绩差与后来演讲比赛夺冠联系起来？","options":["差成绩促使自己在暑假发奋学习，后来汉语成为强项","差成绩本身自动保证后来任何比赛都能获胜","作者从此完全不再学汉语","夺冠与之后的学习没有任何联系"],"answer":"差成绩促使自己在暑假发奋学习，后来汉语成为强项","explanation":"それで把最初成绩差与暑假奮起相连，その結果汉语成为强项并夺冠。最后一句说明若起初成绩好，未必有同样结果；关键是挫折引出的努力，而不是失败自动带来胜利。","point":"理解失败、行动与结果的链条","sourceRoute":"lesson/29/reading/body/9","sourceLabel":"第29课 · 课文／会话精读"},{"id":"CB-R-30","section":"reading","lesson":30,"unitIds":["L30-B015","L30-B016","L30-B017"],"prompt":"作者认为，真正旅行有哪些难以舍弃的魅力？","options":["旅行包含亲身的感动、各种情绪、冒险和与陌生人的相遇","真正旅行完全不用花钱或花时间","所有地图都无法显示城市道路","旅行只需要购买更大的电脑屏幕"],"answer":"旅行包含亲身的感动、各种情绪、冒险和与陌生人的相遇","explanation":"片段承认旅行花钱花时间、会辛苦，但用そこには感動がある以及下一句的喜怒哀楽、冒険、出会い说明亲身经历的价值。","point":"理解让步后的主张","sourceRoute":"lesson/30/reading/body/14","sourceLabel":"第30课 · 课文／会话精读"}],"intermediate":[{"id":"CI-G01","section":"grammar","lesson":1,"unitIds":["I1-G01-E01"],"prompt":"要表达“彼此鼓励、互相帮助”，空格处应选哪一项？","options":["励まし合い","励まされ","励ましすぎ","励ますので"],"answer":"励まし合い","explanation":"「励まし合う」由励ます的连用形励まし接合う构成，表示双方互相鼓励；连用形励まし合い再与助け合い连接。励まされ是被动形式，励ましすぎ表示鼓励过度，都不表示相互动作。","point":"动词连用形＋合う","gap":{"unitId":"I1-G01-E01","start":3,"end":8}},{"id":"CI-G02","section":"grammar","lesson":1,"unitIds":["I1-G02-E01"],"prompt":"要把一则报纸报道作为消息来源，空格处应选哪一项？","options":["によれば","に向かって","に代わって","に先立って"],"answer":"によれば","explanation":"「新聞記事によれば」表示“据某篇报纸报道”，与句末传闻表达そうだ配合。に向かって表示朝向，に代わって表示代替，に先立って表示在某事之前。","point":"消息来源：によれば","gap":{"unitId":"I1-G02-E01","start":6,"end":10}},{"id":"CI-G03","section":"grammar","lesson":2,"unitIds":["I2-G02-E01"],"prompt":"这里要递进表达“不仅没有日本朋友，甚至连交朋友的方法也不知道”，应选哪一项？","options":["どころか","にしたがって","たびに","にかけて"],"answer":"どころか","explanation":"「AどころかB」把情况推进到比A更进一步的B。本句从“一个朋友也没有”进一步说到“不知道怎样交朋友”，并与后面的さえ呼应。其他选项分别表示随同变化、每次、时间或空间范围。","point":"递进：どころか","gap":{"unitId":"I2-G02-E01","start":24,"end":28}},{"id":"CI-G04","section":"grammar","lesson":2,"unitIds":["I2-G04-E01"],"prompt":"要表达“经历一番苦恼之后，最终想到了向报纸求助”，应选哪一项？","options":["あげく","ばかりに","ところで","に対して"],"answer":"あげく","explanation":"「悩んだあげく」强调在一段苦恼、反复考虑的过程之后出现了后面的结果。ばかりに突出造成不良结果的单一原因，ところで与に対して不能在这里表达这段经历之后的结果。","point":"过程后的结果：たあげく","gap":{"unitId":"I2-G04-E01","start":6,"end":9}},{"id":"CI-G05","section":"grammar","lesson":3,"unitIds":["I3-G02-E01"],"prompt":"要表达“虽然叫移动电话，但几乎不存在只能打电话的机型”，应选哪一项？","options":["ものの","ために","ことから","に応じて"],"answer":"ものの","explanation":"「というものの」先承认名称，再提出与该名称通常给人的印象不同的实际情况：电子邮件已成为主要用途。ために、ことから偏向原因或目的，に応じて表示根据条件采取对应变化。","point":"让步转折：ものの","gap":{"unitId":"I3-G02-E01","start":9,"end":12}},{"id":"CI-G06","section":"grammar","lesson":3,"unitIds":["I3-G06-E01"],"prompt":"要说明手机已经成为使用者“不可缺少的存在”，应选哪一项？","options":["なくてはならない","なくてもかまわない","なくなりかねない","なくなったにすぎない"],"answer":"なくてはならない","explanation":"「なくてはならない存在」表示缺少它就不行，即不可或缺。なくてもかまわない表示没有也没关系；なくなりかねない表示可能消失；なくなったにすぎない表示只不过已经消失。","point":"不可缺少：なくてはならない","gap":{"unitId":"I3-G06-E01","start":35,"end":43}},{"id":"CI-G07","section":"grammar","lesson":4,"unitIds":["I4-G01-E01"],"prompt":"要表达“谈日本经济成长就不能不谈商社”，应选哪一项？","options":["を抜きにして","に加えて","と引き換えに","に先立って"],"answer":"を抜きにして","explanation":"「商社を抜きにしては語れない」字面是“省去商社就无法谈论”，强调商社在这一话题中不可忽略。に加えて表示添加，と引き換えに表示交换，に先立って表示时间先后。","point":"不可省略：を抜きにしては～ない","gap":{"unitId":"I4-G01-E01","start":28,"end":34}},{"id":"CI-G08","section":"grammar","lesson":4,"unitIds":["I4-G07-E01"],"prompt":"要表达“泡沫经济一崩溃，国内需求立即停滞”的紧接关系，应选哪一项？","options":["や否や","にしたがって","に先立って","かと思えば"],"answer":"や否や","explanation":"动词辞书形后接や否や，表示前项刚发生，后项就紧接着发生。「崩壊するや否や」突出时间间隔极短；にしたがって强调随之逐步变化，に先立って表示在前。","point":"紧接发生：や否や","gap":{"unitId":"I4-G07-E01","start":36,"end":39}},{"id":"CI-G09","section":"grammar","lesson":5,"unitIds":["I5-G13-E01"],"prompt":"要说明普通商品的定价以进货原价、流通成本等为依据，应选哪一项？","options":["にもとづいて","に反して","にかかわらず","をめぐって"],"answer":"にもとづいて","explanation":"「原価やコストなどにもとづいて」表示依据这些因素作决定。它说明定价的依据；に反して表示相反，にかかわらず表示不受影响，をめぐって表示围绕某个问题。","point":"依据：に基づいて","gap":{"unitId":"I5-G13-E01","start":18,"end":24}},{"id":"CI-G10","section":"grammar","lesson":5,"unitIds":["I5-G10-E01"],"prompt":"要表达“以一百日元这么低的价格来说，质量却相当好”，应选哪一项？","options":["わりに","に応じて","をはじめ","に伴って"],"answer":"わりに","explanation":"「百円のわりに品質は良い」把实际质量与低价通常带来的预期相比，说明质量好于预期。に応じて强调对应，をはじめ用于举代表，に伴って表示伴随变化。","point":"与预期相比：わりに","gap":{"unitId":"I5-G10-E01","start":26,"end":29}},{"id":"CI-G11","section":"grammar","lesson":6,"unitIds":["I6-G02-E01"],"prompt":"要表达“刚穿上机器人辅助装置，就能稳稳行走”，应选哪一项？","options":["とたん","最中に","ままでは","ところでは"],"answer":"とたん","explanation":"「装着したとたん」表示穿戴完成的一瞬间，后面的行走能力变化随即出现。最中に表示某动作进行期间，ままでは表示保持某种状态的条件，不表示完成后立刻出现的变化。","point":"瞬间变化：たとたん","gap":{"unitId":"I6-G02-E01","start":32,"end":35}},{"id":"CI-G12","section":"grammar","lesson":6,"unitIds":["I6-G05-E01"],"prompt":"要提醒先进技术被用于战争或盗窃时“可能成为可怕威胁”，应选哪一项？","options":["かねない","きれない","かねる","得ない"],"answer":"かねない","explanation":"动词连用形后接かねない，表示某种令人担忧的事情有可能发生。「脅威にもなりかねない」是风险判断。かねる表示难以做到，得ない表示不可能，きれない表示无法彻底完成。","point":"不良可能：かねない","gap":{"unitId":"I6-G05-E01","start":46,"end":50}},{"id":"CI-G13","section":"grammar","lesson":7,"unitIds":["I7-G18-E01"],"prompt":"要表达“希望以此为契机，产生认真学习的意愿”，空格处应选哪一项？","options":["をきっかけに","にもかかわらず","に比べて","に反して"],"answer":"をきっかけに","explanation":"「これをきっかけに」表示以这件事为契机，促成后续变化。后面的「勉強する気になってくれればいい」表达希望对方产生认真学习的意愿，并不是说转变已经实现。其余选项分别表示让步、比较和相反，不能表达题目要求的契机关系。","point":"转变的契机：をきっかけに","gap":{"unitId":"I7-G18-E01","start":2,"end":8}},{"id":"CI-G14","section":"grammar","lesson":7,"unitIds":["I7-G10-E01"],"prompt":"要表达“毕竟是升学名校，果然学习内容很难”这种符合预期的评价，应选哪一项？","options":["だけあって","だけでなく","に反して","をよそに"],"answer":"だけあって","explanation":"「進学校だけあって」把升学名校这一特点作为评价依据，与后面的さすがに相呼应，表示难度确实名副其实。に反して表示与预期相反；だけでなく表示不仅，而本句重心是特点与评价相符。","point":"名副其实：だけあって","gap":{"unitId":"I7-G10-E01","start":3,"end":8}},{"id":"CI-G15","section":"grammar","lesson":8,"unitIds":["I8-G09-E01"],"prompt":"要表达“嘴上对家人说只是去看看，实际上早已打算买幼犬”的反差，应选哪一项？","options":["ながら","ために","ならば","ように"],"answer":"ながら","explanation":"这里的ながら表示转折：前项声称只是看看，后项却说明从一开始就准备购买。它不是同时进行两个动作的用法；ために表示原因或目的，ならば表示假定条件。","point":"转折：ながら","gap":{"unitId":"I8-G09-E01","start":13,"end":16}},{"id":"CI-G16","section":"grammar","lesson":8,"unitIds":["I8-G11-E01"],"prompt":"要以感谢、肯定的语气说明小狗让家里重新有了笑容，应选哪一项？","options":["おかげで","せいで","どころか","に反して"],"answer":"おかげで","explanation":"「犬たちのおかげで」把狗狗作为带来良好结果的原因，句末是家中恢复笑容。せいで通常用于追究不良结果；どころか表示递进或反转，に反して表示相反。","point":"有利原因：おかげで","gap":{"unitId":"I8-G11-E01","start":8,"end":12}},{"id":"CI-G17","section":"grammar","lesson":9,"unitIds":["I9-G11-E1"],"prompt":"要表达受到客观条件限制、“不得不改变计划”，应选哪一项？","options":["ざるを得ない","ずにはいられない","ないでもない","ねばならないことはない"],"answer":"ざるを得ない","explanation":"「変更せざるを得ない」表示没有别的办法，只好改变计划；する接ざる时变为せざる。ずにはいられない侧重内心抑制不住的冲动；ないでもない表示并非不，最后一项表示并非必须，均不同于被迫作出的决定。","point":"不得不：ざるを得ない","gap":{"unitId":"I9-G11-E1","start":6,"end":12}},{"id":"CI-G18","section":"grammar","lesson":9,"unitIds":["I9-G5-E1"],"prompt":"要表达作业按照计划推进，应选哪一项？","options":["に沿って","に反して","を除いて","に比べて"],"answer":"に沿って","explanation":"「計画に沿って」表示以计划的方向和内容为准来推进。に反して表示违背，を除いて表示排除，に比べて表示比较，都不能表达这里的遵循关系。","point":"遵循：に沿って","gap":{"unitId":"I9-G5-E1","start":2,"end":6}},{"id":"CI-G19","section":"grammar","lesson":10,"unitIds":["I10-G2-E1"],"prompt":"要表达“从店家方面的立场来看，这是个难题”，应选哪一项？","options":["にしてみれば","にしたがって","に応じて","に先立って"],"answer":"にしてみれば","explanation":"「店側にしてみれば」把观察问题的立场设为店家一方。にしたがって表示遵循或随之变化，に応じて表示根据情况对应，に先立って表示在某事之前。","point":"立场：にしてみれば","gap":{"unitId":"I10-G2-E1","start":2,"end":8}},{"id":"CI-G20","section":"grammar","lesson":10,"unitIds":["I10-G8-E1"],"prompt":"要以强烈反问表达“那种话我才不信”，应选哪一项？","options":["ものか","ものだ","はずだ","ことになる"],"answer":"ものか","explanation":"句末「信じるものか」以反问强烈否定“相信”这件事，意思是决不相信。はずだ表达推断上的应当，ことになる表示结果或决定；本句不是一般性质的说明。","point":"强烈否定：ものか","gap":{"unitId":"I10-G8-E1","start":8,"end":11}},{"id":"CI-G21","section":"grammar","lesson":11,"unitIds":["I11-G2-E1"],"prompt":"要把“变方便”和“原理不易理解”作为同一变化的正反两面，应选哪一项？","options":["反面","結果","おかげで","とおり"],"answer":"反面","explanation":"「便利になった反面」先说便利这一面，再说机制不易理解的另一面。反面连接的是对照的两面；結果、 おかげで强调因果，とおり表示依照或相同。","point":"正反两面：反面","gap":{"unitId":"I11-G2-E1","start":6,"end":8}},{"id":"CI-G22","section":"grammar","lesson":11,"unitIds":["I11-G6-E1"],"prompt":"要表达“以充分讨论的完成为前提，再作出决定”，应选哪一项？","options":["上で","まま","ばかりに","ついでに"],"answer":"上で","explanation":"动词た形后接「上で」，表示先完成前项，再以此为前提进行后项。「話し合った上で決める」要求先充分讨论，再作决定。「まま」表示状态延续，「ばかりに」强调由前项引出不良结果，「ついでに」表示利用做某事的机会顺便做另一件事，均不表达题目要求的准备前提。","point":"完成后再：た上で","gap":{"unitId":"I11-G6-E1","start":7,"end":9}},{"id":"CI-G23","section":"grammar","lesson":12,"unitIds":["I12-G3-E1"],"prompt":"要表达“真正工作之后才第一次理解那种辛苦”，应选哪一项？","options":["初めて","ばかりで","すぐに","いるうちに"],"answer":"初めて","explanation":"「働いて初めて」强调只有经历实际工作，才获得此前没有的认识。すぐに只说很快，并不包含“直到这时才明白”；ばかりで与いるうちに也不表达这一首次领悟。","point":"经历之后才：て初めて","gap":{"unitId":"I12-G3-E1","start":3,"end":6}},{"id":"CI-G24","section":"grammar","lesson":12,"unitIds":["I12-G5-E1"],"prompt":"要把某事限定为“只不过是其中一个原因”，应选哪一项？","options":["にすぎない","によるものだ","に決まっている","にちがいない"],"answer":"にすぎない","explanation":"「理由の一つにすぎない」把它的范围或分量限定为诸多原因之一。「によるものだ」说明某事由前项原因造成，改变了句子的因果关系；「に決まっている」「にちがいない」则加强断定或确信，都不表达题目要求的“仅仅是其中之一”。","point":"限定：にすぎない","gap":{"unitId":"I12-G5-E1","start":8,"end":13}},{"id":"CI-G25","section":"grammar","lesson":13,"unitIds":["I13-G1-E1"],"prompt":"要强调“正因为困难，才想挑战”，应选哪一项？","options":["からこそ","からといって","にしては","に先立って"],"answer":"からこそ","explanation":"「難しいからこそ」中的こそ突出困难正是激发挑战愿望的原因。からといって通常引出不能仅凭前项得出后项的判断，不表示强化原因。","point":"强调原因：からこそ","gap":{"unitId":"I13-G1-E1","start":3,"end":7}},{"id":"CI-G26","section":"grammar","lesson":13,"unitIds":["I13-G4-E1"],"prompt":"要表达说话人“决不再犯同样错误”的坚定意志，应选哪一项？","options":["まい","べきだ","に違いない","ようだ"],"answer":"まい","explanation":"本句的まい是否定意志，表示自己决心不再重复。べきだ表示应当做，に違いない与ようだ用于推断；原句主旨是说话人的决心。","point":"否定意志：まい","gap":{"unitId":"I13-G4-E1","start":12,"end":14}},{"id":"CI-G27","section":"grammar","lesson":14,"unitIds":["I14-G7-E1"],"prompt":"要表达“如果不亲眼看，就无法判断”这一必要条件，应选哪一项？","options":["ないことには","たところで","たからには","るばかりか"],"answer":"ないことには","explanation":"「見ないことには、判断できない」把亲眼看作为作出判断不可缺少的前提。見たところで表示即使看了也……；見たからには以已经看过为前提；見るばかりか用于不仅……甚至……的递进。","point":"必要条件：ないことには","gap":{"unitId":"I14-G7-E1","start":4,"end":10}},{"id":"CI-G28","section":"grammar","lesson":14,"unitIds":["I14-G6-E1"],"prompt":"要表达“以第一次的水平来衡量，做得出乎意料地好”，应选哪一项？","options":["にしては","につれて","にこたえて","を通じて"],"answer":"にしては","explanation":"「初めてにしては」把第一次作为评价基准，实际表现比通常预期更好。につれて表示联动变化，にこたえて表示回应，を通じて表示途径或贯穿范围。","point":"超出预期：にしては","gap":{"unitId":"I14-G6-E1","start":3,"end":7}},{"id":"CI-G29","section":"grammar","lesson":15,"unitIds":["I15-G5-E1"],"prompt":"要表达“必须先确认，不确认就不能发送”，应选哪一项？","options":["てからでないと","たとしても","たばかりに","ているだけで"],"answer":"てからでないと","explanation":"「確認してからでないと、送れません」规定先完成确认才能发送。たとしても表示即使确认了仍不能发送，たばかりに强调确认反而造成不良结果；两者都不表达这里的先后条件。","point":"先完成的条件：てからでないと","gap":{"unitId":"I15-G5-E1","start":3,"end":10}},{"id":"CI-G30","section":"grammar","lesson":15,"unitIds":["I15-G1-E1"],"prompt":"要在方便这一优点之外，再补充安全性高这一优点，应选哪一项？","options":["に加えて","に反して","を除いて","にもかかわらず"],"answer":"に加えて","explanation":"「便利さに加えて、安全性も高い」先提出方便，再追加安全性高，も呼应追加关系。に反して、にもかかわらず偏向相反或让步，を除いて表示排除。","point":"追加：に加えて","gap":{"unitId":"I15-G1-E1","start":3,"end":7}},{"id":"CI-R01","section":"reading","lesson":1,"unitIds":["I1-B002","I1-B003","I1-B004"],"prompt":"依据这几句，学生为什么仍努力增加储蓄？","options":["为了应对求职、升学及不时发生的支出","因为打工收入和家里寄来的钱都显著增加","为了完全停止参加求职活动","因为日常开销已经不需要支付"],"answer":"为了应对求职、升学及不时发生的支出","explanation":"文中先说储蓄用于应对不时之需，后又说明求职和读研究生需要资金。收入减少并没有取消这些未来支出，因此学生压缩开销、提前储备。","point":"理解储蓄的目的"},{"id":"CI-R02","section":"reading","lesson":2,"unitIds":["I2-B005","I2-B006","I2-B007"],"prompt":"这位留学生仍不满足、感到苦恼的核心是什么？","options":["虽然得到一些帮助，仍难与日本同龄人建立朋友关系","打工店里的阿姨从不愿意帮助她","她完全没有机会认识任何日本人","她不愿学习日本家庭料理"],"answer":"虽然得到一些帮助，仍难与日本同龄人建立朋友关系","explanation":"店里的阿姨很亲切，大学女生也提供过帮助，但打工处没有同龄朋友，喝茶邀请又屡遭拒绝。文本区分了获得帮助与建立同龄朋友关系。","point":"区分获得帮助和建立友谊"},{"id":"CI-R03","section":"reading","lesson":3,"unitIds":["I3-B002","I3-B003","I3-B004"],"prompt":"作者怎样说明手机已超出“打电话的工具”这一定位？","options":["功能不断增加，邮件成为重要用途，使用者也逐渐依赖它","所有机型都取消了通话功能","手机只在出门忘带时才有用","年轻人主要用手机取代所有家用电器"],"answer":"功能不断增加，邮件成为重要用途，使用者也逐渐依赖它","explanation":"文中说只有通话功能的机型几乎不存在，年轻人以电子邮件为主要用途；随后说明多功能演进使手机变得不可或缺，忘带还会引起不安。并未说通话被取消或能替代所有家电。","point":"把握多功能化与依赖的联系"},{"id":"CI-R04","section":"reading","lesson":4,"unitIds":["I4-B001","I4-B002","I4-B003"],"prompt":"为什么作者说很难用一句话解释商社？","options":["因为商社一直随时代变化，不能用固定不变的定义简单概括","因为商社与日本经济的成长毫无关系","因为日本已经不存在任何商社","因为商社只从事一种从未改变的业务"],"answer":"因为商社一直随时代变化，不能用固定不变的定义简单概括","explanation":"第二句提出难以一句话说明，第三句用なぜなら明确给出理由：商社随着时代持续变化。第一句还强调商社与日本经济成长关系密切。","point":"识别なぜなら引出的理由"},{"id":"CI-R05","section":"reading","lesson":5,"unitIds":["I5-B008","I5-B009","I5-B010"],"prompt":"店门口的陈列与店内自由浏览安排分别起什么作用？","options":["先以看似超值的商品吸引目光，再让顾客轻松浏览","先要求顾客付款，再允许他们看商品","以严格推销阻止不打算购物的人进入","只展示价格高于一百日元且不能购买的商品"],"answer":"先以看似超值的商品吸引目光，再让顾客轻松浏览","explanation":"入口陈列让人觉得不像一百日元能买到的商品，作用是吸引注意；店内则不论买不买，都让初次来店的顾客自由观看。两者共同降低进店和浏览的压力。","point":"理解店面结构与接客方式"},{"id":"CI-R06","section":"reading","lesson":6,"unitIds":["I6-B008","I6-B009","I6-B010"],"prompt":"按这段说明，辅助行走的装置怎样发挥作用？","options":["传感器取得腿部肌肉信号，再由装置提供行走支持","只要背着电脑就完全不需要腿部装置","把拐杖变成可以独立行走的机器人","不用感知人体信息，仅靠播放声音使人行走"],"answer":"传感器取得腿部肌肉信号，再由装置提供行走支持","explanation":"第八句列出腿部传感器、支撑马达和背负的电脑，第九句说明传感器获取肌肉信号并辅助行走。第十句展示效果，而不是取消人体或传感器的作用。","point":"理解装置工作机制"},{"id":"CI-R07","section":"reading","lesson":7,"unitIds":["I7-B005","I7-B006","I7-B007"],"prompt":"这段文字认为婴儿手语教育首先要实现什么？","options":["让孩子以适合自己的方式表达需求和感受","要求所有手势在形式上完全精确","让婴儿尽快承担成人的日常工作","只让父母学会手语，孩子不参与"],"answer":"让孩子以适合自己的方式表达需求和感受","explanation":"第六句明确说表达不必完全准确，目的是让孩子用自己的方法表达欲求和感受。第七句列举想喝奶、想被抱等需求，说明沟通比手势的形式精确更重要。","point":"辨认教育目的与举例"},{"id":"CI-R08","section":"reading","lesson":8,"unitIds":["I8-B004","I8-B005","I8-B006"],"prompt":"关于去狗店之前的打算，哪一项符合叙述者的自述？","options":["叙述者虽然告诉家人只是看看，其实一开始就打算购买幼犬","叙述者原本坚决不买，直到店员强迫才改变主意","全家出发前已经共同选定了具体犬种","女儿并没有对店里的任何狗产生兴趣"],"answer":"叙述者虽然告诉家人只是看看，其实一开始就打算购买幼犬","explanation":"第五句用と言いながら引出说法与真实意图的反差，并以はじめから明确“从一开始就有购买的打算”。第六句只说女儿到店后对迷你腊肠犬一见钟情。","point":"识别表面说法与真实意图"},{"id":"CI-R09","section":"reading","lesson":9,"unitIds":["I9-B008","I9-B009","I9-B010"],"prompt":"作者从人口结构变化进一步提出了哪两方面的应对课题？","options":["重新审视社会保障，并营造更便于生育和男女共同育儿的社会","完全取消社会保障，并让女性独自承担育儿","只统计人口数字，不调整任何社会制度","以增加老年人口比例作为唯一政策目标"],"answer":"重新审视社会保障，并营造更便于生育和男女共同育儿的社会","explanation":"第九句从社会保障负担扩大提出制度的根本性重审，第十句提出让女性更易生育、男女共同育儿的社会条件。作者没有把责任只交给女性，也没有主张取消保障。","point":"理解结果与应对方向"},{"id":"CI-R10","section":"reading","lesson":10,"unitIds":["I10-B001","I10-B002","I10-B003"],"prompt":"作者为什么特别强调边走边吸烟的危害？","options":["除烟雾和健康影响外，还可能烧坏路人衣服或烫伤孩子","因为这种行为只会影响吸烟者本人","因为它能消除不吸烟者的健康风险","因为所有路人都会因此开始吸烟"],"answer":"除烟雾和健康影响外，还可能烧坏路人衣服或烫伤孩子","explanation":"第二句列出擦肩而过的人的衣服被烧出洞、跑来的孩子面部被烫伤等具体风险；第三句又补充被动吸烟的健康威胁。重点是对周围人的多种伤害。","point":"识别具体例子支持的观点"},{"id":"CI-R11","section":"reading","lesson":11,"unitIds":["I11-B003","I11-B004","I11-B005"],"prompt":"食品种类和信息增加，为什么消费者的不安反而加大？","options":["食品来源变得难以把握，亲自处理食品的机会减少，独立判断所需知识技能也随之流失","因为所有进口食品都已被证明不能食用","因为信息增加就一定能自动提高判断能力","因为家庭烹调和加工食品的次数明显增加"],"answer":"食品来源变得难以把握，亲自处理食品的机会减少，独立判断所需知识技能也随之流失","explanation":"第三句说食品来源变得不明，第四句说家庭调理加工减少，导致了解食品的机会和知识减少；第五句把这些变化归结为判断能力减弱、不安加大。文中并未断言进口食品全部不安全。","point":"整合原因与结果"},{"id":"CI-R12","section":"reading","lesson":12,"unitIds":["I12-B003","I12-B004"],"prompt":"关于成为自由打工者的理由，后一句怎样修正前一句呈现的形象？","options":["并非多数人都主动追求理想生活，很多人是因找不到合适工作或缺乏技能而暂时打工","所有人都已找到理想工作，只是不愿领工资","几乎所有人都完全自愿选择自由打工","只要大学毕业，就一定能被聘为正式员工"],"answer":"并非多数人都主动追求理想生活，很多人是因找不到合适工作或缺乏技能而暂时打工","explanation":"前一句列举优先理想、喜欢工作即可等想法；后一句用しかし、実際には转向现实，指出找不到工作或缺乏技能的情况很多，主动选择这一生活方式的人只占很少一部分。","point":"把握理想说法与现实的对照"},{"id":"CI-R13","section":"reading","lesson":13,"unitIds":["I13-B003","I13-B004","I13-B005"],"prompt":"依文中所述，反对运动要阻止的是什么？","options":["服务被限制、缺口转给家庭或志愿者承担，以及更广泛的福利削减","任何个人自愿帮助他人的活动","对所有家庭成员提供更多正式服务","让残障人士自由选择服务的方式"],"answer":"服务被限制、缺口转给家庭或志愿者承担，以及更广泛的福利削减","explanation":"第三、四句说明服务设上限、使用受限以及家属和志愿者补足缺口，第五句说明反对运动是为了对福利事业的大幅削减喊停。对象是制度性削减，并非否定自愿帮助本身。","point":"理解指示词与反对运动的对象"},{"id":"CI-R14","section":"reading","lesson":14,"unitIds":["I14-B001","I14-B002","I14-B003"],"prompt":"除了学历提高和参与社会工作，作者还指出了哪个重要原因？","options":["必须在某个年龄前结婚的社会压力减弱了","所有女性都被法律禁止结婚","结婚必须达到的法定年龄被取消了","女性已经不能进入社会工作"],"answer":"必须在某个年龄前结婚的社会压力减弱了","explanation":"第三句用しかし补充另一个重要原因：法律实施后，“到某个年龄之前必须结婚”的社会压力减弱。它说的是社会压力的变化，不是禁止结婚或取消法定年龄。","point":"识别补充的社会原因"},{"id":"CI-R15","section":"reading","lesson":15,"unitIds":["I15-B004","I15-B005","I15-B006"],"prompt":"这段对iPod受欢迎原因的说明，突出的是哪一种组合？","options":["时尚设计、小巧机身与大量储存音乐的能力","必须放在桌面使用以及无法随身携带","只受年轻人欢迎而不受中老年人欢迎","外形很大且只能储存一首音乐"],"answer":"时尚设计、小巧机身与大量储存音乐的能力","explanation":"第四句交代可储存音乐并随身携带；第五句说明受众已扩展至中老年人；第六句把时尚设计、小巧机身与大容量并列为人气的秘密。这里依据课文对当时产品的描述作答。","point":"提取产品特点与人气原因"}],"advanced":[{"id":"CA-G-A1-G1-E1","section":"grammar","lesson":1,"unitIds":["A1-G1-E1"],"prompt":"选择表示“着手开展调查之际”的表达。","options":["にあたって","にひきかえ","に忍びない","をよそに"],"answer":"にあたって","explanation":"「にあたって」接动词辞书形，表示开展某项活动之际。句中是在开始调查时先确定记录办法；其他选项分别表示对照、不忍做和不顾某事，不能表达这里的准备场景。","point":"にあたって","gap":{"unitId":"A1-G1-E1","start":6,"end":11},"sourceRoute":"lesson/1/notes/0"},{"id":"CA-G-A1-G2-E1","section":"grammar","lesson":1,"unitIds":["A1-G2-E1"],"prompt":"要表达“以上次的指点为依据，重新缩小问题范围”，空格应填什么？","options":["を踏まえて","をよそに","をめぐって","をものともせず"],"answer":"を踏まえて","explanation":"「を踏まえて」把已有指点作为重新判断的基础。「をよそに」是不顾，「をめぐって」是围绕议题，「をものともせず」是不畏障碍，都没有表达题目要求的依据关系。","point":"を踏まえて","gap":{"unitId":"A1-G2-E1","start":5,"end":10},"sourceRoute":"lesson/1/notes/1"},{"id":"CA-G-A2-G1-E1","section":"grammar","lesson":2,"unitIds":["A2-G1-E1"],"prompt":"选择标示“通常被认为如此”的表达。","options":["とされる","に至る","を前提に","ともなく"],"answer":"とされる","explanation":"「とされる」承接完整判断「資料ごとに意味が異なる」，把这一判断表述为通常被接受的认识。它本身不等于说话人已亲自证实。","point":"とされる","gap":{"unitId":"A2-G1-E1","start":17,"end":21},"sourceRoute":"lesson/2/notes/0"},{"id":"CA-G-A2-G2-E1","section":"grammar","lesson":2,"unitIds":["A2-G2-E1"],"prompt":"要交代后文信息来自“调查报告”，空格应选什么？","options":["によれば","に応じて","にひきかえ","を皮切りに"],"answer":"によれば","explanation":"「によれば」标明消息或判断的来源，后面的「という」与之呼应。这里是在转述报告内容，而不是根据条件作调整、对比对象或说明系列事件的起点。","point":"によれば","gap":{"unitId":"A2-G2-E1","start":4,"end":8},"sourceRoute":"lesson/2/notes/1"},{"id":"CA-G-A3-G1-E1","section":"grammar","lesson":3,"unitIds":["A3-G1-E1"],"prompt":"选择表示“解读会取决于资料的定位方式”的表达。","options":["いかんで","をよそに","に至るまで","ともあろう"],"answer":"いかんで","explanation":"「名词＋いかんで」表示结果取决于前项的内容或处理方式。句中「読み方も変わる」正说明解读随定位方式而变化。","point":"いかんで","gap":{"unitId":"A3-G1-E1","start":7,"end":11},"sourceRoute":"lesson/3/notes/0"},{"id":"CA-G-A3-G2-E1","section":"grammar","lesson":3,"unitIds":["A3-G2-E1"],"prompt":"要表达“译词选择关系到概念理解”，应选哪一项？","options":["にかかわる","にかかわらず","に先立って","にもまして"],"answer":"にかかわる","explanation":"「にかかわる」表示涉及、关系到重要事项；「にかかわらず」则是无论某条件如何。这里讨论的是译词选择与概念理解之间的关联。","point":"にかかわる","gap":{"unitId":"A3-G2-E1","start":12,"end":17},"sourceRoute":"lesson/3/notes/1"},{"id":"CA-G-A4-G1-E1","section":"grammar","lesson":4,"unitIds":["A4-G1-E1"],"prompt":"选择把“参观展览”作为后续查考活动开端的表达。","options":["を皮切りに","に至っては","をよそに","に忍びない"],"answer":"を皮切りに","explanation":"「を皮切りに」表示以某事件为开端，随后继续一系列活动。后面的「調べ始めた」承接了由参观转向进一步调查的过程。","point":"を皮切りに","gap":{"unitId":"A4-G1-E1","start":5,"end":10},"sourceRoute":"lesson/4/notes/0"},{"id":"CA-G-A4-G2-E1","section":"grammar","lesson":4,"unitIds":["A4-G2-E1"],"prompt":"选择突出“没有留下记录的经验”这一更难处理的特殊情况的表达。","options":["に至っては","に先立って","を前提に","を皮切りに"],"answer":"に至っては","explanation":"「に至っては」提出较特殊、极端或更棘手的一例。没有记录可供核对，更需要谨慎，正是本句的评价推进。","point":"に至っては","gap":{"unitId":"A4-G2-E1","start":9,"end":14},"sourceRoute":"lesson/4/notes/1"},{"id":"CA-G-A5-G1-E1","section":"grammar","lesson":5,"unitIds":["A5-G1-E1"],"prompt":"要表达“仿佛在表示拒绝”，并保留这只是感受而非已确认事实，空格应填什么？","options":["かのように","に応じて","を前提に","をめぐって"],"answer":"かのように","explanation":"「かのように」接在普通形后作方式修饰，表示仿佛如此。它与「感じられた」共同标出主观感受，不把沉默直接判定为拒绝。","point":"かのようだ","gap":{"unitId":"A5-G1-E1","start":8,"end":13},"sourceRoute":"lesson/5/notes/0"},{"id":"CA-G-A5-G2-E1","section":"grammar","lesson":5,"unitIds":["A5-G2-E1"],"prompt":"要表达“并无明确观看目标，只是漫无目的地望着窗外”，应选什么？","options":["ともなく","べく","にあたって","がゆえに"],"answer":"ともなく","explanation":"「見るともなく」表示没有明确意图或目标地看。若选「べく」反而会引出明确目的；其余选项表示着手之际或原因。","point":"ともなく","gap":{"unitId":"A5-G2-E1","start":4,"end":8},"sourceRoute":"lesson/5/notes/1"},{"id":"CA-G-A6-G1-E2","section":"grammar","lesson":6,"unitIds":["A6-G1-E2"],"prompt":"选择表示“无论是哪一个版本，都要核对省略的意义”的表达。","options":["であれ","に応じて","をめぐって","を皮切りに"],"answer":"であれ","explanation":"「どの版であれ」把不同版本作为不影响后项原则的条件。后项的核对要求适用于任何版本。","point":"であれ","gap":{"unitId":"A6-G1-E2","start":3,"end":6},"sourceRoute":"lesson/6/notes/0"},{"id":"CA-G-A6-G2-E1","section":"grammar","lesson":6,"unitIds":["A6-G2-E1"],"prompt":"要表达“沉默比台词更令人印象深刻”，应填什么？","options":["にもまして","を皮切りに","に先立って","を前提に"],"answer":"にもまして","explanation":"「にもまして」表示与前项相比，后项更加突出。这里比较台词与沉默留下印象的程度，并不表示时间先后或成立前提。","point":"にもまして","gap":{"unitId":"A6-G2-E1","start":2,"end":7},"sourceRoute":"lesson/6/notes/1"},{"id":"CA-G-A7-G1-E1","section":"grammar","lesson":7,"unitIds":["A7-G1-E1"],"prompt":"选择描绘“仿佛马上就要哭出来”的强烈状态的表达。","options":["んばかりに","にかたくない","にすぎず","をよそに"],"answer":"んばかりに","explanation":"「泣き出す」的ない形词干是「泣き出さ」，后接「んばかりに」形成「泣き出さんばかりに」。它描绘几乎要哭的样子，不断言已经哭了。","point":"んばかりに","gap":{"unitId":"A7-G1-E1","start":9,"end":14},"sourceRoute":"lesson/7/notes/0"},{"id":"CA-G-A7-G2-E1","section":"grammar","lesson":7,"unitIds":["A7-G2-E1"],"prompt":"要写出“她的行动仿佛在说‘不再犹豫’”，而非引用她实际说过的话，应选什么？","options":["とばかりに","を前提に","に先立って","によれば"],"answer":"とばかりに","explanation":"「とばかりに」使行动或神态呈现出仿佛说了某句话的意味。按下发送按钮表现出决断；句子没有说她真的开口说出了这句话。","point":"とばかりに","gap":{"unitId":"A7-G2-E1","start":6,"end":11},"sourceRoute":"lesson/7/notes/1"},{"id":"CA-G-A8-G1-E1","section":"grammar","lesson":8,"unitIds":["A8-G1-E1"],"prompt":"选择表示“在访谈正式开始之前，先说明使用目的”的表达。","options":["に先立って","にひきかえ","をよそに","をものともせず"],"answer":"に先立って","explanation":"「に先立って」接在活动名词后，表示在重要活动之前先做准备。本句把说明使用目的放在访谈开始之前。","point":"に先立って","gap":{"unitId":"A8-G1-E1","start":4,"end":9},"sourceRoute":"lesson/8/notes/0"},{"id":"CA-G-A8-G2-E2","section":"grammar","lesson":8,"unitIds":["A8-G2-E2"],"prompt":"要表达“以本人核对为成立基础，再确定引用范围”，应填什么？","options":["を前提に","をよそに","にひきかえ","にもまして"],"answer":"を前提に","explanation":"「を前提に」表示把前项条件作为后续安排的基础。这里引用范围的确定以本人确认作为前提，不是忽视本人意见或比较其程度。","point":"を前提に","gap":{"unitId":"A8-G2-E2","start":5,"end":9},"sourceRoute":"lesson/8/notes/1"},{"id":"CA-G-A9-G1-E1","section":"grammar","lesson":9,"unitIds":["A9-G1-E1"],"prompt":"选择提醒“使用未核实说明可能导致散布错误信息”这一不良结果的表达。","options":["かねない","がたい","べく","ともなく"],"answer":"かねない","explanation":"「動词ます形去ます＋かねない」表示可能发生不希望出现的结果。「広め」后接「かねない」，风险对象是散布错误信息；「がたい」表示难以做到，意思不同。","point":"かねない","gap":{"unitId":"A9-G1-E1","start":17,"end":21},"sourceRoute":"lesson/9/notes/0"},{"id":"CA-G-A9-G2-E1","section":"grammar","lesson":9,"unitIds":["A9-G2-E1"],"prompt":"选择表示“存在令人担忧的可能性”的表达。","options":["おそれがある","に忍びない","にかたくない","を皮切りに"],"answer":"おそれがある","explanation":"「普通形＋おそれがある」说明值得担心的可能结果。这里担心的是根据不明时，答案本身却先传播出去；并不是说这一结果已经发生。","point":"おそれがある","gap":{"unitId":"A9-G2-E1","start":18,"end":24},"sourceRoute":"lesson/9/notes/1"},{"id":"CA-G-A10-G1-E1","section":"grammar","lesson":10,"unitIds":["A10-G1-E1"],"prompt":"要说明“重做确认画面，是为了减少询问中的错误”，应选什么？","options":["べく","ともなく","ものを","に忍びない"],"answer":"べく","explanation":"「動词辞书形＋べく」表示为了某目标采取行动。「減らすべく」标出目标，重做确认画面是为实现目标而主动采取的办法。","point":"べく","gap":{"unitId":"A10-G1-E1","start":13,"end":15},"sourceRoute":"lesson/10/notes/0"},{"id":"CA-G-A10-G2-E1","section":"grammar","lesson":10,"unitIds":["A10-G2-E1"],"prompt":"要严肃批评某行为“有失指导者应负的责任”，应选什么？","options":["にあるまじき","ならではの","に先立つ","いかんで"],"answer":"にあるまじき","explanation":"「身份名词＋にあるまじき＋名词」批评与该身份责任不相称的行为。「指導者にあるまじき態度」对应未经确认便责备他人的态度。","point":"にあるまじき","gap":{"unitId":"A10-G2-E1","start":17,"end":23},"sourceRoute":"lesson/10/notes/1"},{"id":"CA-G-A11-G3-E1","section":"grammar","lesson":11,"unitIds":["A11-G3-E1"],"prompt":"要表达字幕的改进“不限于照顾听觉差异，还改变观看顺序”，应填什么？","options":["にとどまらず","にすぎず","をよそに","に先立って"],"answer":"にとどまらず","explanation":"「にとどまらず」先提出一个作用范围，再指出作用进一步扩展。后项「見る順序も変えた」说明字幕改进还有更广的影响；「にすぎず」反而会限制其范围。","point":"にとどまらず","gap":{"unitId":"A11-G3-E1","start":18,"end":24},"sourceRoute":"lesson/11/notes/2"},{"id":"CA-G-A11-G2-E1","section":"grammar","lesson":11,"unitIds":["A11-G2-E1"],"prompt":"选择与后面的「さえ」呼应，表示“别说安静房间，连使用书桌的时间也难保障”的表达。","options":["はおろか","に先立って","を前提に","にもまして"],"answer":"はおろか","explanation":"「はおろか」与「さえ」构成程度推进：安静的房间难以保障，连较基本的书桌使用时间也不容易确保。应按这两个项目的关系理解整句。","point":"はおろか","gap":{"unitId":"A11-G2-E1","start":5,"end":9},"sourceRoute":"lesson/11/notes/1"},{"id":"CA-G-A12-G1-E1","section":"grammar","lesson":12,"unitIds":["A12-G1-E1"],"prompt":"要表达“即便是用母语说话的人，也同样受理解限制”，应选什么？","options":["にしたところで","を皮切りに","に至るまで","にあたって"],"answer":"にしたところで","explanation":"「人物・立场＋にしたところで」把被认为更有利的一方也纳入同样的限制。母语者也并不能总是准确理解他人的意图。","point":"にしたところで","gap":{"unitId":"A12-G1-E1","start":6,"end":13},"sourceRoute":"lesson/12/notes/0"},{"id":"CA-G-A12-G2-E1","section":"grammar","lesson":12,"unitIds":["A12-G2-E1"],"prompt":"要表达“即使用国籍解释差异，也未必能知道当前需要什么调整”，应填什么？","options":["ところで","とたんに","だけに","ばかりに"],"answer":"ところで","explanation":"「動词た形＋ところで」表示即使做了前项，也难以获得期待的后项结果。这里「説明した」已在空格前，故只补「ところで」。","point":"たところで","gap":{"unitId":"A12-G2-E1","start":10,"end":14},"sourceRoute":"lesson/12/notes/1"},{"id":"CA-G-A13-G1-E1","section":"grammar","lesson":13,"unitIds":["A13-G1-E1"],"prompt":"要表达“无论小组安排如何，准备时间都应得到保障”，应选什么？","options":["にかかわらず","にかかわる","をめぐって","に至るまで"],"answer":"にかかわらず","explanation":"「にかかわらず」表示前项条件的差异不改变后项原则；「にかかわる」表示涉及，不是本句要求的让步条件。","point":"にかかわらず","gap":{"unitId":"A13-G1-E1","start":4,"end":10},"sourceRoute":"lesson/13/notes/0"},{"id":"CA-G-A13-G2-E1","section":"grammar","lesson":13,"unitIds":["A13-G2-E1"],"prompt":"选择把“日程改变”作为当前特殊情形，并引出必须联系参与者的反应的表达。","options":["とあっては","とはいえ","と思いきや","かのように"],"answer":"とあっては","explanation":"「とあっては」表示既然出现这种特殊情况，就不得不采取后述措施。后面的「連絡しなければならない」明确表达了由情形引出的必要行动。","point":"とあっては","gap":{"unitId":"A13-G2-E1","start":6,"end":11},"sourceRoute":"lesson/13/notes/1"},{"id":"CA-G-A14-G1-E1","section":"grammar","lesson":14,"unitIds":["A14-G1-E1"],"prompt":"要表达“即便承认问题相同，仍不能认为回答条件相同”，应填什么？","options":["であるにせよ","にあるまじき","を皮切りに","に忍びない"],"answer":"であるにせよ","explanation":"名词「同じ質問」后用「であるにせよ」作郑重的让步表达。它承认问题相同，却保留后项关于回答条件的判断。","point":"であるにせよ","gap":{"unitId":"A14-G1-E1","start":4,"end":10},"sourceRoute":"lesson/14/notes/0"},{"id":"CA-G-A14-G2-E1","section":"grammar","lesson":14,"unitIds":["A14-G2-E1"],"prompt":"要表达“根据资料性质的不同，作出相应的展示选择”，应选什么？","options":["に応じて","をよそに","にもまして","をものともせず"],"answer":"に応じて","explanation":"「に応じて」表示随某条件或变化作对应调整。这里展示方式应与资料性质相匹配，不是无视性质或克服性质这个障碍。","point":"に応じて","gap":{"unitId":"A14-G2-E1","start":5,"end":9},"sourceRoute":"lesson/14/notes/1"},{"id":"CA-G-A15-G1-E1","section":"grammar","lesson":15,"unitIds":["A15-G1-E1"],"prompt":"要用带有责问意味的表达，强调“身为研究者，却如此行事不相称”，应填什么？","options":["ともあろう","に応じた","を前提にした","に先立つ"],"answer":"ともあろう","explanation":"「研究者ともあろう者が」借身份与行为的落差表达责问。「ともあろう」不是一般中性身份介绍，后文质问的正是回避不利记录的做法。","point":"ともあろう","gap":{"unitId":"A15-G1-E1","start":3,"end":8},"sourceRoute":"lesson/15/notes/0"},{"id":"CA-G-A15-G2-E1","section":"grammar","lesson":15,"unitIds":["A15-G2-E1"],"prompt":"要补出“未经确认，不可责人”这一带古典语感的禁止警语，应选什么？","options":["べからず","べく","にすぎない","かのようだ"],"answer":"べからず","explanation":"「動词辞书形＋べからず」表示不可做某事，常见于警句或规训语境。这里「という戒め」明确说明它是一句提醒自己遵守的禁止性警语。","point":"べからず","gap":{"unitId":"A15-G2-E1","start":10,"end":14},"sourceRoute":"lesson/15/notes/1"},{"id":"CA-G-A16-G1-E1","section":"grammar","lesson":16,"unitIds":["A16-G1-E1"],"prompt":"要对“没有早点商议，结果独自烦恼”表示惋惜，句末应填什么？","options":["ものを","にすぎない","かねない","べく"],"answer":"ものを","explanation":"「ものを」在本句承接反事实条件，带出本可避免遗憾的惋惜。早点商议本可不必独自烦恼，但实际没有做到。","point":"ものを","gap":{"unitId":"A16-G1-E1","start":20,"end":23},"sourceRoute":"lesson/16/notes/0"},{"id":"CA-G-A16-G2-E1","section":"grammar","lesson":16,"unitIds":["A16-G2-E1"],"prompt":"要暂时评估稿件进度为“大致只能说开始看得出骨架”，应选什么？","options":["といったところだ","に忍びない","にあるまじき","べからず"],"answer":"といったところだ","explanation":"「といったところだ」表示大致到某种程度，常含目前至多如此的评估。「ようやく」「見え始めた」也说明稿件尚处于初步成形阶段。","point":"といったところだ","gap":{"unitId":"A16-G2-E1","start":17,"end":25},"sourceRoute":"lesson/16/notes/1"},{"id":"CA-G-A17-G1-E1","section":"grammar","lesson":17,"unitIds":["A17-G1-E1"],"prompt":"要表示“原以为声音会发抖，实际却说得更快”这一意外转折，应填什么？","options":["と思いきや","に応じて","べく","を皮切りに"],"answer":"と思いきや","explanation":"「と思いきや」把先前预想与出乎意料的实际情况连接起来。它不是为了某目标而主动选择说快，也不是按条件作调整。","point":"と思いきや","gap":{"unitId":"A17-G1-E1","start":5,"end":10},"sourceRoute":"lesson/17/notes/0"},{"id":"CA-G-A17-G2-E1","section":"grammar","lesson":17,"unitIds":["A17-G2-E1"],"prompt":"要带着自嘲回顾“发表前的自己，满脑子只在意稿件措辞”，应选什么？","options":["ときたら","に応じて","に先立って","を条件に"],"answer":"ときたら","explanation":"「名词＋ときたら」提出对象并接较强的评价。这里回顾自己过分在意措辞的状态，带有自嘲，而不是中性的条件或时间说明。","point":"ときたら","gap":{"unitId":"A17-G2-E1","start":6,"end":10},"sourceRoute":"lesson/17/notes/1"},{"id":"CA-G-A18-G1-E1","section":"grammar","lesson":18,"unitIds":["A18-G1-E1"],"prompt":"要强调话题覆盖范围甚至扩展到“图书馆介绍的阅读方式”，应填什么？","options":["に至るまで","を皮切りに","にひきかえ","を前提に"],"answer":"に至るまで","explanation":"「に至るまで」强调范围扩展到较细或出人意料的一端。这里不是以阅读介绍为起点展开活动，而是说讨论连这一细节也涉及了。","point":"に至るまで","gap":{"unitId":"A18-G1-E1","start":10,"end":15},"sourceRoute":"lesson/18/notes/0"},{"id":"CA-G-A18-G2-E1","section":"grammar","lesson":18,"unitIds":["A18-G2-E1"],"prompt":"要叙述她“不畏语言不熟悉这一障碍，仍接连提问”，应选什么？","options":["をものともせず","を前提に","をめぐって","に応じて"],"answer":"をものともせず","explanation":"「をものともせず」表示不把困难或障碍放在眼里，仍然采取行动。句中的障碍是「慣れない言葉」，持续行动是「質問を重ねた」。","point":"をものともせず","gap":{"unitId":"A18-G2-E1","start":6,"end":13},"sourceRoute":"lesson/18/notes/1"},{"id":"CA-R-01","section":"reading","lesson":1,"unitIds":["A1-B004","A1-B005","A1-B006"],"prompt":"老师建议记录具体场景，这些记录在王明的研究中起了什么作用？","options":["帮助他把游玩经验转化为可以继续追问的问题","使他不再需要向其他人了解游玩经验","证明他喜欢的作品比其他作品更适合研究","让他只需描述场景，无须提出研究问题"],"answer":"帮助他把游玩经验转化为可以继续追问的问题","explanation":"王明先记下选择之后想起未选道路的经验，再基于记录追问后悔与选择机制的关系。记录在这里是形成研究问题的材料。","point":"课文内容理解","sourceRoute":"lesson/1/reading/body/3"},{"id":"CA-R-02","section":"reading","lesson":2,"unitIds":["A2-B003","A2-B004","A2-B006"],"prompt":"林洋为什么要把调查对象、地点和时间补回草稿？","options":["避免把特定调查参与者的情况扩大成人类的一般性质","使摘要尽可能保留原文的全部措辞与排列顺序","证明调查对象越多，摘要的说服力就一定越强","让读者只关注调查结果，不必区分确认与推测"],"answer":"避免把特定调查参与者的情况扩大成人类的一般性质","explanation":"草稿删去了原文的限定条件，导致特定参与者的情况被读成普遍性质。补回对象、地点和时间，是恢复主张适用的范围，并区分确认与推测。","point":"课文内容理解","sourceRoute":"lesson/2/reading/body/2"},{"id":"CA-R-03","section":"reading","lesson":3,"unitIds":["A3-B002","A3-B003","A3-B004"],"prompt":"同样的汉字词在不同文章中出现时，这段文字主张怎样理解？","options":["结合文章面向谁、针对什么问题，辨别同一个词的不同论述位置","先把同一汉字统一译成同一个现代术语，再比较结论","以是否涉及个人为唯一标准，排除涉及集体关系的文章","只要在词典中确认了词义，便可把不同文章中的含义视为相同"],"answer":"结合文章面向谁、针对什么问题，辨别同一个词的不同论述位置","explanation":"相同汉字不保证含义相同：有的文章谈个人判断，有的谈群体与外部的关系。面向的读者和所处理的问题会影响具体解读。","point":"课文内容理解","sourceRoute":"lesson/3/reading/body/1"},{"id":"CA-R-04","section":"reading","lesson":4,"unitIds":["A4-B003","A4-B004","A4-B005"],"prompt":"工作人员为何建议先确认照片的拍摄目的？","options":["照片中的微笑不能直接证明人物对日常生活毫无不满","照片中的制服足以说明孩子们当时生活幸福","建筑物的外观比照片中的人物表情更能确定拍摄日期","纪念照中出现的表情通常与真实情绪完全相反"],"answer":"照片中的微笑不能直接证明人物对日常生活毫无不满","explanation":"文本明确区分在纪念照中微笑与日常生活没有不满。核对拍摄目的，是避免把特定拍摄场景中的表现直接推成对整体生活的判断。","point":"课文内容理解","sourceRoute":"lesson/4/reading/body/2"},{"id":"CA-R-05","section":"reading","lesson":5,"unitIds":["A5-B003","A5-B004","A5-B005"],"prompt":"田中最初的判断与文本实际写出的内容有什么区别？","options":["田中感到这是母亲的拒绝，但文本只明确写出回应没有马上到来","田中认为母亲没有回应，文本却已明确说明母亲在拒绝","田中从叙述者的直接说明中得知了母亲的完整心理","田中把母亲的主动邀请误读成了年轻人的犹豫"],"answer":"田中感到这是母亲的拒绝，但文本只明确写出回应没有马上到来","explanation":"田中把未立即回应理解为拒绝，但寻找根据时发现文本只写明回应没有马上到来。因此需要区分人物或读者的解释与叙述者明确展示的事实。","point":"课文内容理解","sourceRoute":"lesson/5/reading/body/2"},{"id":"CA-R-06","section":"reading","lesson":6,"unitIds":["A6-B005","A6-B006","A6-B007"],"prompt":"这段文字对影像表现方式的评价是什么？","options":["影像有其独特的表达手段，但这并不构成影像优于文字的结论","只要使用声音，影像就不再需要展示人物动作","沉默一旦有效，就应删除所有台词和人物动作","回复被删掉的动作证明影像能够完全呈现人物内心"],"answer":"影像有其独特的表达手段，但这并不构成影像优于文字的结论","explanation":"手的动作、电车的声音以及输入后删除回复的细节体现影像的表达特点；文本随即说明，这不意味着影像本身比其他媒介优越。","point":"课文内容理解","sourceRoute":"lesson/6/reading/body/4"},{"id":"CA-R-07","section":"reading","lesson":7,"unitIds":["A7-B003","A7-B004","A7-B005"],"prompt":"依照这段文字，下列哪种情况可能使“自己作出决定”的实感减弱？","options":["结局虽有分岔，玩家却事先不理解选项意味着什么","不同回复最终到达同一地点，但传达给他人的内容不同","选项数目较少，玩家却清楚每个选项的意义","玩家在选择前已经知道当前场景发生在哪里"],"answer":"结局虽有分岔，玩家却事先不理解选项意味着什么","explanation":"文本直接指出：即使结局分岔，若事先不明白选项含义，也可能缺少自己作决定的实感。不能只凭选项数量或结局数量判断自由。","point":"课文内容理解","sourceRoute":"lesson/7/reading/body/2"},{"id":"CA-R-08","section":"reading","lesson":8,"unitIds":["A8-B005","A8-B007","A8-B008"],"prompt":"这段文字认为，调查者应怎样理解参与者的同意？","options":["不能把参加上映会或研究的同意，自动扩大成对所有资料用途的同意","只要同意录音，便可以默认允许公开参与者的声音","参加上映会本身就表示对相关访谈已有合作义务","只需说明调查主题，录音、保存与公开可在之后统一决定"],"answer":"不能把参加上映会或研究的同意，自动扩大成对所有资料用途的同意","explanation":"参加上映会不等于当然协助研究；同意录音也可能不包括公开声音。参与研究与同意资料的全部使用方式必须分别确认。","point":"课文内容理解","sourceRoute":"lesson/8/reading/body/4"},{"id":"CA-R-09","section":"reading","lesson":9,"unitIds":["A9-B003","A9-B004","A9-B005"],"prompt":"发现一本所列文献暂时找不到时，林洋在这一阶段应当怎样处理？","options":["保留对原因的判断，且不把未读到的内容当作已读文献来介绍","立即断定该书不存在，并把其他所列文献也全部视为虚构","依照工具的流畅说明，先完整介绍该书内容再补查来源","只要书名符合主题，就可以省略对书目信息的进一步核实"],"answer":"保留对原因的判断，且不把未读到的内容当作已读文献来介绍","explanation":"原文说尚不能判断是书不存在还是书目信息部分有误，但这一不确定状态并不允许把未读内容当成自己读过的文献介绍。","point":"课文内容理解","sourceRoute":"lesson/9/reading/body/2"},{"id":"CA-R-10","section":"reading","lesson":10,"unitIds":["A10-B006","A10-B007","A10-B009"],"prompt":"小组如何区分可以自动推进的工作和需要人确认的工作？","options":["按作业分别列明界线，向外发送询问前由人核对对象、时间和文面","把查询公开信息与确定预约视为同一类操作，一并交给工具","只要文面由人提供过一次，后续对象和时间均不需再确认","以工具是否使用自然语言作为判断全部权限的唯一标准"],"answer":"按作业分别列明界线，向外发送询问前由人核对对象、时间和文面","explanation":"查询与确定预约之间有重要差别，因此小组按具体作业列出自动与人工确认的界线；对外发送询问时，要求人核对对象、时间和文面。","point":"课文内容理解","sourceRoute":"lesson/10/reading/body/5"},{"id":"CA-R-11","section":"reading","lesson":11,"unitIds":["A11-B006","A11-B007","A11-B008"],"prompt":"线上会场为何并未消除参加的条件？","options":["连接、声音、操作和现实中的设备与安静空间仍影响参加","线上参加者必须与实体会场使用完全相同的交通方式","只要拥有专用设备，所有人就会获得相同的参与条件","人不必到现场，因此声音和操作的差异不再重要"],"answer":"连接、声音、操作和现实中的设备与安静空间仍影响参加","explanation":"不必来到实体地点不等于参加条件消失。实际测试仍发现连接、声音、操作问题，设备与安静房间也影响参与的便利程度。","point":"课文内容理解","sourceRoute":"lesson/11/reading/body/5"},{"id":"CA-R-12","section":"reading","lesson":12,"unitIds":["A12-B004","A12-B005","A12-B006"],"prompt":"这段文字提醒，不宜仅凭发言时长判断贡献，原因是什么？","options":["组织措辞的速度或所用语言的差异，可能被误当作能力差异","发言较少的人一定比发言较多的人提出更重要的问题","会后提交笔记足以取代一切现场交流和确认","会议话题越快推进，越能避免语言差异影响讨论"],"answer":"组织措辞的速度或所用语言的差异，可能被误当作能力差异","explanation":"会后的笔记提出了重要疑问，而当事人在组织措辞期间话题已转移。仅以时长评价，会把表达条件与思路整理速度的差异误认成能力差异。","point":"课文内容理解","sourceRoute":"lesson/12/reading/body/3"},{"id":"CA-R-13","section":"reading","lesson":13,"unitIds":["A13-B005","A13-B006","A13-B007"],"prompt":"郑决定在窗口分别询问哪两件事？","options":["说明中哪些表达含糊，以及现在是否仍有可使用的方法","职员为何写出错误说明，以及自己是否可以免除所有申请手续","谁应承担全部责任，以及怎样取消其他人的会场使用","职员是否赞同研究主题，以及如何改变研究会的内容"],"answer":"说明中哪些表达含糊，以及现在是否仍有可使用的方法","explanation":"郑意识到窗口职员未必就是说明的撰写者，于是先展示自己的理解，再把文字含糊之处与当下可行的利用办法分开询问。","point":"课文内容理解","sourceRoute":"lesson/13/reading/body/4"},{"id":"CA-R-14","section":"reading","lesson":14,"unitIds":["A14-B005","A14-B006","A14-B007"],"prompt":"人数与比例的比较得出不同顺序，这段文字认为首先应明确什么？","options":["究竟要比较赞同者的数量，还是其在参与者中所占的比例","究竟应删除A组人数，还是删除B组比例以保持结论一致","究竟哪一组的数据真实，另一组的数据必定计算错误","究竟选用哪一种数字才能始终得出B组赞同更强的结论"],"answer":"究竟要比较赞同者的数量，还是其在参与者中所占的比例","explanation":"人数与比例回答的是不同问题。作者并未判定其中一种数字错误，而是指出说明没有先确定比较目的；比较占比还必须展示分母。","point":"课文内容理解","sourceRoute":"lesson/14/reading/body/4"},{"id":"CA-R-15","section":"reading","lesson":15,"unitIds":["A15-B004","A15-B005","A15-B006"],"prompt":"重新听取那位参与者的记录后，小组面临什么需要修正的认识？","options":["原先的提问方式可能没有涵盖不同经验，而非参与者经验本身不充分","所有没有犹豫的玩家都应从分析中排除，以保持资料同质","只要多数人经验相同，少数人的说明就不具有分析价值","玩家未选择的道路比当前所在场景更能客观衡量其投入程度"],"answer":"原先的提问方式可能没有涵盖不同经验，而非参与者经验本身不充分","explanation":"该参与者关注的是当前所在之处能做什么，而不是未选的道路。与其他经验不同不等于经验不充分，反而可能暴露原先问题预设的局限。","point":"课文内容理解","sourceRoute":"lesson/15/reading/body/3"},{"id":"CA-R-16","section":"reading","lesson":16,"unitIds":["A16-B004","A16-B005","A16-B006"],"prompt":"王明缩短文章后出现的主要问题是什么？","options":["具体要解释的问题被一般论替代，文章反而难以说明本次弄清了什么","一般论本身已被证明完全错误，因此全文所有结论都应撤回","短句必然比长句缺少论证，所以应恢复原来的全部字数","只要保留个人差异这一表述，就能完整解释两个场景中的经验差别"],"answer":"具体要解释的问题被一般论替代，文章反而难以说明本次弄清了什么","explanation":"原来追问两个场景中经验为何不同的段落，被“经验存在个人差异”替换。一般论未必错，却使本次具体分析的贡献和问题位置变得不清楚。","point":"课文内容理解","sourceRoute":"lesson/16/reading/body/3"},{"id":"CA-R-17","section":"reading","lesson":17,"unitIds":["A17-B003","A17-B004","A17-B005"],"prompt":"田中希望王明在进入分析细节前先向听众提供什么？","options":["为何选取这一场景，以及接下来应关注或比较什么的线索","作品全部背景材料的逐项介绍，即使因此无法进入分析","只报告分析结论，不再说明选取场景的理由与比较对象","听众已经熟悉作品的假定，以便直接使用所有专业术语"],"answer":"为何选取这一场景，以及接下来应关注或比较什么的线索","explanation":"练习时王明未解释为何选该场景就进入细节；田中指出听众未必了解作品，需要先获得关注线索。文本也说明不必交代全部背景，但应让人知道接下来比较什么。","point":"课文内容理解","sourceRoute":"lesson/17/reading/body/2"},{"id":"CA-R-18","section":"reading","lesson":18,"unitIds":["A18-B003","A18-B004","A18-B005"],"prompt":"面对不同背景的听众，单纯减少专业术语为什么还不够？","options":["如果问题和前提仍未得到说明，日常词语也可能让听众难以进入讨论","因为公开读书会只能使用统一的专业术语体系","因为日常词语比专业词语更难被所有人理解","因为研究问题应当在讨论结束后才第一次向听众公开"],"answer":"如果问题和前提仍未得到说明，日常词语也可能让听众难以进入讨论","explanation":"文本指出：减少术语却不让问题显现，无法建立说明入口；即使只用日常词语，若误以为前提已共享，仍可能把听众落在后面。","point":"课文内容理解","sourceRoute":"lesson/18/reading/body/2"}]};
